-- Initial seed for the existing rental, service-area, and FAQ content.
WITH seeded_rental_rates AS (
  SELECT * FROM jsonb_to_recordset($rates$[{"name":"2-Seater Golf Cart","passenger_capacity":2,"daily_price_zar":850,"weekly_price_zar":5100,"monthly_price_zar":25000,"includes_delivery":true,"display_order":0},{"name":"4-Seater Golf Cart","passenger_capacity":4,"daily_price_zar":1100,"weekly_price_zar":6800,"monthly_price_zar":30000,"includes_delivery":true,"display_order":1},{"name":"6-Seater Golf Cart","passenger_capacity":6,"daily_price_zar":1400,"weekly_price_zar":8000,"monthly_price_zar":38000,"includes_delivery":true,"display_order":2},{"name":"Utility Golf Cart","passenger_capacity":null,"daily_price_zar":1500,"weekly_price_zar":9200,"monthly_price_zar":41000,"includes_delivery":true,"display_order":3}]$rates$::jsonb) AS item(
    name text, passenger_capacity integer, daily_price_zar bigint,
    weekly_price_zar bigint, monthly_price_zar bigint,
    includes_delivery boolean, display_order integer
  )
)
INSERT INTO public.rental_rates (
  name, passenger_capacity, daily_price_zar, weekly_price_zar,
  monthly_price_zar, includes_delivery, display_order
)
SELECT name, passenger_capacity, daily_price_zar, weekly_price_zar,
  monthly_price_zar, includes_delivery, display_order
FROM seeded_rental_rates;

WITH seeded_service_areas AS (
  SELECT * FROM jsonb_to_recordset($areas$[{"slug":"eastern-cape","name":"Eastern Cape","towns":["Gqeberha","East London","Makhanda","Kariega","Mthatha"],"overview":"The Eastern Cape spans coastal cities, smaller towns and rural destinations. If you are comparing a golf cart for a home, golf course, hospitality venue or worksite, share the intended use and town so the relevant specifications and arrangements can be discussed.","useCases":["Golf and leisure facilities around Gqeberha and East London","Guest transport at coastal and inland hospitality properties","Movement around private properties and managed sites"],"considerations":"The province covers a wide area. Confirm the delivery destination, lead time and any transport costs before proceeding, and check that the cart suits the surface and daily distance you have in mind."},{"slug":"free-state","name":"Free State","towns":["Bloemfontein","Welkom","Bethlehem","Kroonstad","Sasolburg"],"overview":"From Bloemfontein to the towns across the interior, Free State enquiries can involve golf, accommodation, private-property or operational use. Start with the number of passengers, typical route and how often the cart will be used.","useCases":["Short trips at golf clubs and leisure venues","Guest movement at accommodation and event properties","Everyday transport around private premises"],"considerations":"Distances between towns can affect transport arrangements. Ask for the full delivered cost and expected timing for your specific address, rather than relying on a province-wide estimate."},{"slug":"gauteng","name":"Gauteng","towns":["Johannesburg","Pretoria","Centurion","Midrand","Sandton"],"overview":"Gauteng enquiries come from a mix of residential estates, golf facilities, hospitality venues and business properties. To narrow down suitable options, share your suburb or estate, passenger requirements and whether you are considering a purchase or rental.","useCases":["Golf courses, residential estates and leisure facilities","Guest transport at hotels, venues and event properties","Short-distance movement around campuses and work sites"],"considerations":"Access rules differ between estates, clubs and commercial properties. Check permission for golf-cart use at your destination and confirm delivery access and arrangements before placing an order."},{"slug":"kwazulu-natal","name":"KwaZulu-Natal","towns":["Durban","Pietermaritzburg","Ballito","Richards Bay","Newcastle"],"overview":"KwaZulu-Natal includes coastal centres, inland towns and holiday destinations. Tell us where the cart will be used and whether it is for a golf facility, guest accommodation, private property or another permitted purpose.","useCases":["Golf and resort properties along the coast and inland","Guest transport at accommodation and holiday venues","Short-distance use around private or managed properties"],"considerations":"Coastal conditions, storage and the route surface can matter when choosing a cart. Confirm the cart's specifications, maintenance needs and transport arrangements for your particular location."},{"slug":"limpopo","name":"Limpopo","towns":["Polokwane","Tzaneen","Bela-Bela","Mokopane","Phalaborwa"],"overview":"Limpopo's towns and tourism destinations can have very different requirements. For an enquiry from Polokwane, Bela-Bela, Tzaneen or elsewhere in the province, describe the terrain, daily distance and passenger load you need to support.","useCases":["Guest movement at lodges and tourism properties","Golf and leisure facilities in towns and resort areas","Short-distance transport around private properties"],"considerations":"For lodge, rural or uneven-ground use, confirm the vehicle's capabilities and intended operating environment with CartScout. Delivery feasibility and costs need to be checked for the exact destination."},{"slug":"mpumalanga","name":"Mpumalanga","towns":["Mbombela (Nelspruit)","White River","Hazyview","Secunda","Ermelo"],"overview":"Mpumalanga enquiries may come from towns, golf facilities, accommodation and tourism properties. Include the closest town, the route surface and how the cart will be used so that suitability and transport can be discussed clearly.","useCases":["Guest transport at accommodation and tourism properties","Golf courses and leisure venues around Mbombela and White River","Movement around private estates and managed sites"],"considerations":"Properties near the escarpment or outside major towns may have specific access and terrain needs. Confirm that a cart is suitable for the route and check delivery details against the full address."},{"slug":"north-west","name":"North West","towns":["Rustenburg","Mahikeng","Potchefstroom","Klerksdorp","Sun City"],"overview":"North West combines university towns, regional centres and leisure destinations. A useful enquiry describes whether the cart is for a golf course, hospitality property, estate or worksite, along with the number of passengers and typical trip length.","useCases":["Golf, resort and leisure properties","Guest movement at accommodation and event venues","Short trips around campuses and private sites"],"considerations":"A golf cart may not be suitable for every road or worksite. Check local operating rules, route conditions and any site permissions, then confirm availability and delivery for your destination."},{"slug":"northern-cape","name":"Northern Cape","towns":["Kimberley","Upington","Kathu","Springbok","De Aar"],"overview":"The Northern Cape is a large province with significant distances between towns. Whether your enquiry is from Kimberley, Upington or another area, the exact delivery address and intended use are important when checking a suitable cart and transport options.","useCases":["Golf and leisure venues in regional centres","Guest transport at accommodation and tourism properties","Short-distance movement around large private premises"],"considerations":"Long-distance transport may affect cost and timing. Share the full destination and ask for delivery arrangements to be confirmed in writing before making a decision."},{"slug":"western-cape","name":"Western Cape","towns":["Cape Town","Stellenbosch","Paarl","George","Knysna"],"overview":"Western Cape enquiries span metropolitan areas, Winelands towns and Garden Route destinations. Share the town or suburb, passenger count and intended setting to help clarify which listed cart or rental request may be relevant.","useCases":["Golf facilities and residential properties","Guest transport at wine, hospitality and event venues","Short-distance movement around managed properties"],"considerations":"A venue's access rules, terrain and route length can affect cart suitability. Confirm operating permissions and the full delivery or rental arrangements for your location."}]$areas$::jsonb) AS item(
    slug text, name text, towns jsonb, overview text,
    "useCases" jsonb, considerations text
  )
)
INSERT INTO public.service_areas (
  slug, name, towns, overview, use_cases, considerations, display_order
)
SELECT slug, name, towns, overview, "useCases", considerations,
  row_number() OVER (ORDER BY slug)::integer - 1
FROM seeded_service_areas
ON CONFLICT (slug) DO NOTHING;

WITH seeded_faqs AS (
  SELECT * FROM jsonb_to_recordset($faqs$[{"question":"How are catalogue prices calculated?","answer":"Each catalogue price is calculated from its source USD price using the exchange rate shown on the inventory page and rounded to whole rand.","category":"general","display_order":0,"is_published":true},{"question":"Are catalogue prices shown in South African rand?","answer":"Yes. Catalogue prices and the passenger-capacity price guide are displayed in whole-rand South African rand (ZAR).","category":"general","display_order":1,"is_published":true},{"question":"Are the golf carts in CartScout's collection available in South Africa?","answer":"CartScout sells and rents golf carts throughout South Africa. Contact us about your preferred make and model, and we will arrange delivery to your location.","category":"general","display_order":2,"is_published":true},{"question":"How do I request a golf cart price in rand?","answer":"Select “Enquire to buy” on a cart and include your town or province in the purchase enquiry. The listed catalogue price is shown on the product card.","category":"general","display_order":3,"is_published":true},{"question":"How much does golf cart hire or rental cost?","answer":"The rentals page shows daily, weekly, and monthly rates for several passenger capacities and utility carts. For custom dates, multiple carts, or special requirements, send your location and details to CartScout for a quote.","category":"general","display_order":4,"is_published":true},{"question":"Does sending an enquiry reserve a golf cart or confirm a rental?","answer":"No. An email, call, or WhatsApp message is only an enquiry. A purchase or rental is confirmed only after availability, the final price, and the applicable terms are agreed.","category":"general","display_order":5,"is_published":true},{"question":"What affects the price of a golf cart?","answer":"Price can depend on make, model, year, passenger capacity, condition, battery or powertrain, accessories, and transport. For an imported cart, ask whether any import-related costs apply and get the full amount confirmed in writing.","category":"general","display_order":6,"is_published":true},{"question":"How many seats should I choose?","answer":"Start with the number of passengers and any equipment or cargo you need to carry. Check the stated capacity and intended use with CartScout; the price guide groups listed carts by passenger capacity.","category":"general","display_order":7,"is_published":true},{"question":"Are the listed golf carts new or used?","answer":"Do not infer a cart's condition from its model year or product title. Ask CartScout to confirm whether it is new or used, its condition, service history, and any warranty before proceeding.","category":"general","display_order":8,"is_published":true},{"question":"Does a golf cart include its battery and charger?","answer":"Inclusions vary by cart. Confirm the battery type and condition, charger, accessories, and warranty with CartScout before agreeing to a purchase.","category":"general","display_order":9,"is_published":true},{"question":"Can a golf cart be delivered to my province?","answer":"Yes. CartScout serves customers across South Africa. Share your full address and preferred timing so we can arrange delivery and confirm the details for your purchase.","category":"general","display_order":10,"is_published":true},{"question":"Can I drive a golf cart on public roads in South Africa?","answer":"Do not assume a golf cart is permitted on public roads. Requirements can depend on the vehicle, road, and applicable national or local rules. Check with the relevant traffic authority and municipality before using one on a public road.","category":"general","display_order":11,"is_published":true},{"question":"Can I request carts for an event or group?","answer":"Yes. CartScout rents golf carts throughout South Africa. Share the event location, dates, passenger count, and number of carts so we can arrange delivery and confirm availability.","category":"general","display_order":12,"is_published":true},{"question":"How can I check a cart before buying it?","answer":"Contact CartScout to arrange a vehicle inspection and discuss the cart specifications, service history, included equipment, and applicable warranty.","category":"general","display_order":13,"is_published":true},{"question":"Which areas can I request golf cart hire in?","answer":"CartScout rents golf carts throughout South Africa. Share your town or delivery address, dates, and passenger requirements so we can arrange availability, delivery, and collection.","category":"rental","display_order":0,"is_published":true},{"question":"How much does golf cart hire cost?","answer":"The rental rates table lists daily, weekly, and monthly rates for 2-seater, 4-seater, 6-seater, and utility carts. Confirm your dates and any request-specific terms with CartScout.","category":"rental","display_order":1,"is_published":true},{"question":"Can I hire for a day, a week, or longer?","answer":"The rate guide includes daily, weekly, and monthly periods. For a different duration or multiple carts, include your dates and requirements in a request for custom pricing.","category":"rental","display_order":2,"is_published":true},{"question":"Is the cart booked when I send a request?","answer":"No. A WhatsApp message, call, or email is only an enquiry. Your rental is not booked until CartScout confirms availability and you agree to the quote and rental terms.","category":"rental","display_order":3,"is_published":true},{"question":"Can I request carts for an event or group?","answer":"You can include the number of carts, passenger needs, location, dates, and intended use in your enquiry. CartScout will check whether the request can be accommodated.","category":"rental","display_order":4,"is_published":true},{"question":"What is included in the rental price?","answer":"Each rate states whether delivery and collection are included. Confirm timing, any additional costs, vehicle inclusions, and rental conditions for your request before accepting a quote.","category":"rental","display_order":5,"is_published":true}]$faqs$::jsonb) AS item(
    category text, question text, answer text,
    display_order integer, is_published boolean
  )
)
INSERT INTO public.faqs (category, question, answer, display_order, is_published)
SELECT category, question, answer, display_order, is_published
FROM seeded_faqs;
